/* Structural (not just visual) responsive changes — like swapping a table for a stacked
   card list — need to know the viewport in JS, since that's a different DOM shape, not
   something pure CSS can toggle. Driven by matchMedia, the same width-based mechanism
   the CSS breakpoints use, kept in sync automatically as the window resizes. */
const useIsMobile = () => {
  const [mobile, setMobile] = useState(() => typeof window !== "undefined" && window.matchMedia("(max-width: 767px)").matches);
  useEffect(() => {
    const mq = window.matchMedia("(max-width: 767px)");
    const onChange = e => setMobile(e.matches);
    mq.addEventListener ? mq.addEventListener("change", onChange) : mq.addListener(onChange);
    return () => { mq.removeEventListener ? mq.removeEventListener("change", onChange) : mq.removeListener(onChange); };
  }, []);
  return mobile;
};

