const FONTS = `
@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700&family=IBM+Plex+Mono:wght@400;500;600&family=Inter:wght@400;500;600;700&display=swap');

/* Light / dark mode. Only the "surface" colours change — page background, panel
   background, borders, primary/secondary text. The brand green and the status colours
   (proficiency levels, certification status) are deliberately fixed in both themes,
   since they carry meaning that should read the same regardless of light or dark. */
:root {
  --c-ink: #1B2420; --c-paper: #EEF1EC; --c-card: #FFFFFF; --c-line: #D6DCD3; --c-dim: #5E6B62;
  --c-panel: #F2F5F0; --c-row: #F7F9F5; --c-input: #FBFCF9; --c-disabled: #F1F3EF;
  --c-warn-bg: #FFF6DC; --c-danger-bg: #FBEAEA; --c-info-bg: #E8EEF7;
  --c-chart-neutral: #262626;
  --c-chart-train: #843C0C; --c-chart-cert: #5B5B5B; --c-chart-core: #1F3864; --c-chart-adv: #5B3B86;
}
[data-theme="dark"] {
  --c-ink: #EAF0EC; --c-paper: #121815; --c-card: #1C2620; --c-line: #445A4F; --c-dim: #93A199;
  /* Secondary surfaces — nested panels, inputs, expanded table rows, and tinted status
     banners. These were left as hardcoded near-white literals when the theme was first
     added, which is exactly why text stopped reading well: C.ink/C.dim already flip to
     light colours in dark mode, so light text was landing on backgrounds that never
     stopped being near-white. Every one of those literals below is now a variable. */
  --c-panel: #1E2924; --c-row: #202B25; --c-input: #223028; --c-disabled: #17201B;
  --c-warn-bg: #26200F; --c-danger-bg: #201414; --c-info-bg: #0E161D;
  /* Chart-only overrides — do not affect the small STATUS_BG-driven badges elsewhere,
     which already read fine as bordered, white-on-colour chips. --c-chart-neutral IS
     STATUS_BG[0]'s own value (see STATUS_BG definition) so Matrix and Dashboard always
     show the identical colour for "level 0" — recalibrated so white badge text stays
     legible on it (5.05:1) while remaining visible against the dark card (3.09:1). */
  --c-chart-neutral: #657268;
  --c-chart-train: #E8944F; --c-chart-cert: #B8C4BC; --c-chart-core: #6FA8DC; --c-chart-adv: #B48EE0;
}
/* Print / Save-as-PDF: only the report overlay is printed, everything else is hidden.
   Uses the browser's native print dialog (Save as PDF is a print-destination option in
   every modern browser) rather than a PDF-generation library, so there is no extra
   dependency and the output always matches what is on screen. */
@media print {
  body * { visibility: hidden; }
  #nesr-print-report, #nesr-print-report * { visibility: visible; -webkit-print-color-adjust: exact; print-color-adjust: exact; color-adjust: exact; }
  #nesr-print-report { position: absolute; top: 0; left: 0; width: 100%; margin: 0; padding: 0; }
  .no-print { display: none !important; }
  .print-page-break { page-break-before: always; }
  @page { margin: 12mm; }
}

/* ============================================================
   Responsive layout — three width bands, driven purely by CSS media queries
   (never user-agent sniffing): Desktop >=1180px keeps the current design exactly as
   built; Tablet 768-1179px is the same structure with tightened spacing; Mobile
   <768px is the one genuinely redesigned surface (condensed header, sticky-first-
   column tables, full-width stacked filters/forms). Rules use !important because
   they intentionally override the existing inline styles at each element — that is
   the established, standard way to layer breakpoint behaviour onto inline-styled
   React without rewriting every component's style object.
   ============================================================ */

/* ---- Tablet (768-1179px): tighten, do not restructure ---- */
@media (max-width: 1179px) {
  .nesr-team-logo { height: 52px !important; }
  .nesr-hdr-meta-item.hide-tablet { display: none !important; }
  .nesr-kpi-tile { min-width: 118px !important; padding: 8px 10px !important; }
}

/* ---- Mobile (<768px): the redesigned surface ---- */
@media (max-width: 767px) {
  .nesr-team-logo { height: 36px !important; }
  .nesr-hdr-title { font-size: 15px !important; }
  .nesr-hdr-meta-item.hide-mobile { display: none !important; }
  .nesr-hdr-meta-item { padding: 3px 7px !important; }
  .nesr-hdr-meta-item .v { font-size: 10px !important; }

  /* Every table gets a sticky first column so row identity stays visible while
     scrolling horizontally — the universal fallback for tables not yet converted
     to the full card layout (see EmployeeCard below for that pattern). */
  .nesr-table td:first-child, .nesr-table th:first-child {
    position: sticky !important; left: 0 !important; z-index: 3 !important;
    box-shadow: 2px 0 4px rgba(0,0,0,0.08) !important;
  }
  .nesr-table td, .nesr-table th { font-size: 12px !important; padding: 5px 7px !important; }

  .nesr-kpi-tile { min-width: 47% !important; flex: 1 1 47% !important; }
  .nesr-filter-bar { flex-direction: column !important; align-items: stretch !important; }
  .nesr-filter-bar > * { width: 100% !important; }
  .nesr-filter-bar select, .nesr-filter-bar input { min-width: 0 !important; width: 100% !important; }
  .nesr-chart-card { min-width: 0 !important; flex-basis: 100% !important; }

  /* Cards use the sticky-column table's own zebra background for the sticky cell,
     so it doesn't show through as transparent while scrolling. */
  .nesr-table td:first-child { background: inherit; }
}
`;

