const TRAIN_MODES = ["Training Class", "OJT", "Self Training"];
const dupCount = (rows, key) => { const seen = new Set(); let n = 0; rows.forEach(r => { const v = (r[key] || "").trim(); if (!v) return; if (seen.has(v)) n++; else seen.add(v); }); return n; };
const dedupe = (rows, key) => { const seen = new Set(); return rows.filter(r => { const v = (r[key] || "").trim(); if (!v) return true; if (seen.has(v)) return false; seen.add(v); return true; }); };
const elementTrainings = catalog => catalog.filter(r => r.element)
  .flatMap(r => TRAIN_MODES.map(m => ({ name: `${r.element} ${m}`, notes: `Element: ${r.element}` })));
const CERT_REQ_DEFAULT = ["X","X","","","X","X","","","X"];   // In House + Online required; Tech + Practical required
/* Declared here, not beside the other certification helpers, because SEED and EMPTY
   below reference it at module-load time — a later `const` would be in the temporal
   dead zone and throw "Cannot access 'CERT_DEFAULT_ROLES' before initialization". */
const CERT_DEFAULT_ROLES = ["Operator"];
/* Every certification gets its own In House Training course in the Training catalog. */
const certTrainings = certCatalog => (certCatalog || []).filter(c => c.name)
  .map(c => ({ name: `${c.name} Training Class`, notes: `Certification: ${c.name}` }));
/* Progression groups — named services rather than the old A-E letters. Editable in
   Administration -> Framework and Records -> Progression Groups. */
/* A group is either EXCLUSIVE — an element may belong to only one of these, its primary
   service band — or additional, which any number of elements may also carry alongside
   their exclusive group. */
const DEFAULT_PROGRESSION_GROUPS = [
  { name:"Core Services",    exclusive:true,  notes:"Primary service band" },
  { name:"Advance Services", exclusive:true,  notes:"Primary service band" },
  { name:"Special Services", exclusive:true,  notes:"Primary service band" },
  { name:"Unconventional",   exclusive:false, notes:"Additional grouping — combines with a primary band" },
];
/* Old letter codes map onto the named groups so existing catalog rows carry over. */
const GROUP_LETTER_MAP = { A:"Core Services", B:"Advance Services", C:"Unconventional", D:"Special Services", E:"Special Services" };
const groupDefs = s => ((s && s.progressionGroups) || DEFAULT_PROGRESSION_GROUPS);
/* Country and location lists used by the Employee register — editable in
   Administration -> Framework and Records -> Countries & Locations. */
const countryOpts = s => (s && s.countries && s.countries.length) ? s.countries : L.country;
/* Locations are {name, country}. A location with no country set is treated as global and
   offered under every country, so nothing disappears if the link is left blank. */
const locationDefs = s => {
  const raw = (s && s.locations && s.locations.length) ? s.locations : L.location;
  return raw.map(x => typeof x === "string" ? { name:x, country:"" } : { name:x.name, country:x.country || "" });
};
const locationOpts = (s, country) => {
  const defs = locationDefs(s);
  if (!country) return defs.map(l => l.name);
  return defs.filter(l => !l.country || l.country === country).map(l => l.name);
};
const groupNames = s => groupDefs(s).map(g => g.name).filter(Boolean);
const isExclusiveGroup = (s, name) => !!groupDefs(s).find(g => g.name === name)?.exclusive;
const elementGroups = r => Array.isArray(r?.groups) ? r.groups : (r?.group ? [r.group] : []);
/* Adding an exclusive group replaces whichever exclusive group was there before —
   an element can only sit in one primary band. Additional groups simply accumulate. */
const withGroupAdded = (s, current, name) => {
  const cur = current || [];
  if (cur.includes(name)) return cur;
  if (!isExclusiveGroup(s, name)) return [...cur, name];
  return [...cur.filter(g => !isExclusiveGroup(s, g)), name];
};

