/* ============================================================================
   CDP linking — connecting the booklet's requirement names to the real
   certification/proficiency/training engines
   ============================================================================
   Two ways a requirement can resolve to a real catalog entry:
   1. AUTOMATIC — the requirement's own booklet name matches a catalog entry
      exactly. Kept as a convenience default, not the primary path.
   2. EXPLICIT — an admin has picked a specific catalog entry via the "Link"
      control in Administration -> Catalog -> CDP Steps, stored as
      requirement.linkedName. This takes priority over the automatic match,
      because it's how a booklet requirement gets connected to an EXISTING
      catalog entry that's worded differently — "Explosives Operations"
      (booklet) linked to "Explosives Certification" (your catalog) — without
      needing to rename anything or create a near-duplicate entry.
   No fuzzy matching anywhere in either path — a wrong automatic guess is a
   worse failure than an honest "not linked yet", so both paths are exact
   string equality, one automatic and one admin-chosen. */
const cdpFindCert = (state, name) => (state.certCatalog || []).find(c => c.name === name) || null;
const cdpFindElement = (state, name) => (state.catalog || []).find(c => c.element === name) || null;
const cdpFindTraining = (state, name) => (state.trainCatalog || []).find(c => c.name === name) || null;

// The name actually used to resolve a requirement: the explicit admin link
// if one is set, otherwise the booklet's own wording.
const cdpResolvedName = (req, bookletField) => req.linkedName || req[bookletField];

function cdpCertLinkStatus(state, empId, certReq) {
  const resolvedName = cdpResolvedName(certReq, "name");
  const cert = cdpFindCert(state, resolvedName);
  if (!cert) return { linked: false, code: null, displayName: resolvedName };
  const st = computeCertStatus(state, empId, cert);
  return { linked: true, code: certStatusCode(st), cert, displayName: cert.name };
}
function cdpCompetencyLinkStatus(state, d, empId, compReq) {
  const resolvedName = cdpResolvedName(compReq, "element");
  const el = cdpFindElement(state, resolvedName);
  if (!el) return { linked: false, level: null, met: false, displayName: resolvedName };
  const level = d.maxProfOrNull ? d.maxProfOrNull(empId, resolvedName) : null;
  const effLevel = level == null ? 0 : level;
  return { linked: true, level: effLevel, met: effLevel >= compReq.level, displayName: el.element };
}
function cdpTrainingLinkStatus(state, trainReq) {
  const resolvedName = cdpResolvedName(trainReq, "name");
  const t = cdpFindTraining(state, resolvedName);
  return t ? { linked: true, displayName: t.name } : { linked: false, displayName: resolvedName };
}

/* Reconciliation — per step, how many of its requirements resolve to a real
   catalog entry (automatically or via an explicit link) vs. still need one.
   Used by the "Catalog link status" panel. */
function cdpReconcileStep(state, step) {
  const certs = step.certifications.map(c => { const cert = cdpFindCert(state, cdpResolvedName(c, "name")); return { ...c, found: !!cert, displayName: cert ? cert.name : cdpResolvedName(c, "name") }; });
  const elements = step.competency.map(c => { const el = cdpFindElement(state, cdpResolvedName(c, "element")); return { ...c, found: !!el, displayName: el ? el.element : cdpResolvedName(c, "element") }; });
  const training = step.inHouseTraining.map(t => { const link = cdpTrainingLinkStatus(state, t); return { ...t, found: link.linked, displayName: link.displayName }; });
  return {
    certs, elements, training,
    certsFound: certs.filter(c => c.found).length, certsTotal: certs.length,
    elementsFound: elements.filter(c => c.found).length, elementsTotal: elements.length,
    trainingFound: training.filter(t => t.found).length, trainingTotal: training.length,
  };
}

/* Mutations — link/unlink, add, remove a single requirement row within one
   step's one category. All immutable, all keyed by stepKey + index so the
   UI never needs to touch the array shape directly. */
function cdpSetLink(set, stepKey, category, idx, linkedName) {
  set(s => ({ ...s, cdpSteps: (s.cdpSteps || []).map(st => st.key !== stepKey ? st : {
    ...st, [category]: st[category].map((item, i) => i !== idx ? item : { ...item, linkedName: linkedName || undefined }),
  }) }));
}
function cdpAddRequirement(set, stepKey, category, newItem) {
  set(s => ({ ...s, cdpSteps: (s.cdpSteps || []).map(st => st.key !== stepKey ? st : {
    ...st, [category]: [...st[category], newItem],
  }) }));
}
function cdpRemoveRequirement(set, stepKey, category, idx) {
  set(s => ({ ...s, cdpSteps: (s.cdpSteps || []).map(st => st.key !== stepKey ? st : {
    ...st, [category]: st[category].filter((_, i) => i !== idx),
  }) }));
}


/* ============================================================================
   CDP employee progress — the per-employee record and its status computation
   ============================================================================
   state.cdpProgress: one row per tracked employee — { empId, stepKey,
   stepStart, values, inHouseDone, notes }. "values" is a flat { [promotionKey]:
   value } bag rather than fixed named fields, because Step 4's promotion
   list has entirely different keys (tenderParticipation, clientSupportDays,
   supervisoryDays...) from Steps 1-3 (hseMeetings, techPresentations...) —
   a fixed schema would force awkward unused fields per step. "inHouseDone"
   is a { [moduleName]: boolean } map, since in-house training modules have
   no engine to link to (unlike certifications/competency) and stay a plain
   manual checklist, same reasoning as promotion values.

   ASSUMPTION FLAGGED: the booklet references "min rated C" / "min rated B"
   appraisal thresholds but never shows the full rating scale anywhere in the
   document. CDP_RATING_ORDER below is a reasonable standard 4-tier guess
   (D worst - A best), not confirmed against a real NESR appraisal scale —
   this should be corrected to match whatever scale HR actually uses before
   this gates any real promotion decision. */
const CDP_RATING_ORDER = ["D", "C", "B", "A"];
const cdpRatingMeets = (actual, minRequired) => {
  if (!actual) return false;
  const ai = CDP_RATING_ORDER.indexOf(actual), mi = CDP_RATING_ORDER.indexOf(minRequired);
  return ai >= 0 && mi >= 0 && ai >= mi;
};

const cdpFindProgress = (state, empId) => (state.cdpProgress || []).find(r => r.empId === empId) || null;
const cdpFindStep = (state, stepKey) => (state.cdpSteps || []).find(s => s.key === stepKey) || null;

/* L.step (the employee record's own CDP step field, already editable in
   Administration -> Employees) and cdpSteps are both ordered Step 1-4 —
   position-matched here rather than string-matched on wording, which is
   more robust if either list's exact phrasing ever changes. "Management
   Development" (L.step's 5th value, beyond Step 4) has no corresponding
   entry in cdpSteps on purpose — that stage is past the CDP steps this
   booklet covers, not a gap in the mapping. */
const cdpStepKeyFromEmployeeStep = (state, employeeStepLabel) => {
  const idx = (L.step || []).indexOf(employeeStepLabel);
  if (idx < 0 || idx >= (state.cdpSteps || []).length) return null;
  return state.cdpSteps[idx].key;
};

/* The full computed picture for one employee: every requirement in every
   category, whether it's met, and an overall readiness verdict. Read-only —
   this never writes anything; it only reads the linked engines plus
   whatever manual values have been entered. Step and step-start date come
   from the employee's own record (state.employees), not a separately
   tracked value — one source of truth, matching how the rest of the app
   already treats an employee's CDP step as their own field. */
function cdpEmployeeStatus(state, d, empId) {
  const emp = (state.employees || []).find(e => e.id === empId);
  if (!emp) return null;
  const progress = cdpFindProgress(state, empId);
  const stepKey = cdpStepKeyFromEmployeeStep(state, emp.step);
  const step = stepKey ? cdpFindStep(state, stepKey) : null;
  if (!step) return { emp, progress, step: null, monthsIn: null, certs: [], competency: [], inHouse: [], promotion: [], ready: false };

  const monthsIn = emp.stepStart ? monthsBetween(parseD(emp.stepStart) || today(), today()) : null;
  const values = progress?.values || {};
  const inHouseDone = progress?.inHouseDone || {};

  const certs = step.certifications.map(c => {
    const link = cdpCertLinkStatus(state, empId, c);
    const met = link.linked && link.code === 3;
    return { ...c, ...link, met };
  });
  const competency = step.competency.map(c => {
    const link = cdpCompetencyLinkStatus(state, d, empId, c);
    return { ...c, ...link, met: link.linked && link.met };
  });
  const inHouse = step.inHouseTraining.map(t => ({ ...t, met: !!inHouseDone[t.name] }));

  const promotion = step.promotion.map(p => {
    const v = values[p.key];
    let met = false;
    if (p.unit === "min-rating") met = cdpRatingMeets(v, p.target);
    else met = (typeof v === "number" ? v : parseFloat(v) || 0) >= p.target;
    return { ...p, value: v, met };
  });

  const allRequiredMet = arr => arr.filter(x => x.required !== false).every(x => x.met);
  const ready = allRequiredMet(certs) && allRequiredMet(competency) && inHouse.every(x => x.met) && promotion.every(x => x.met);

  return { progress, step, monthsIn, certs, competency, inHouse, promotion, ready };
}


