/* ---------------- date + status helpers (exact port of workbook formulas) ---------------- */
const today = () => { const d = new Date(); return new Date(d.getFullYear(), d.getMonth(), d.getDate()); };
const parseD = s => { if (!s) return null; const d = new Date(s + "T00:00:00"); return isNaN(d) ? null : d; };
const addMonths = (d, m) => { const r = new Date(d); r.setMonth(r.getMonth() + m); return r; };
const monthsBetween = (a, b) => { let m = (b.getFullYear() - a.getFullYear()) * 12 + (b.getMonth() - a.getMonth()); if (b.getDate() < a.getDate()) m -= 1; return Math.max(0, m); };
const fmtD = s => { const d = parseD(s); return d ? d.toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" }) : "—"; };

const trainingStatus = r => {
  if (!r.empId) return null;
  if (r.result === "Pass") {
    // A pass is only valid until the record's own expiry — previously it read as
    // valid forever, so lapsed training still showed 3 on the matrix.
    const ex = parseD(r.expiry);
    if (!ex) return 3;                                   // no expiry set = does not lapse
    if (ex < today()) return 1;                          // lapsed
    if (ex <= addMonths(today(), 2)) return 2;           // lapsing within 2 months
    return 3;
  }
  const start = parseD(r.startDate);
  if (!start) return 0;
  if (start <= addMonths(today(), 3)) return 2;
  if (start <= addMonths(today(), 6)) return 1;
  return 0;
};
const certStatus = r => {
  if (!r.empId) return null;
  if (!r.issueDate) return 0;
  const ex = parseD(r.expiryDate);
  if (!ex) return 3;
  if (ex < today()) return 1;
  if (ex <= addMonths(today(), 2)) return 2;
  return 3;
};
const CERT_LABEL = ["No done","Expired","Expires ≤ 2 months","Valid"];
const wlComplexity = (surf, sub) => (surf === "" || sub === "") ? null : Math.round(((+surf + +sub) / 6) * 5 * 100) / 100;

/* ---------------- CDP Progress Tracker import (external HR export -> Employee register) ---------------- */
const CDP_MONTHS = { Jan:0, Feb:1, Mar:2, Apr:3, May:4, Jun:5, Jul:6, Aug:7, Sep:8, Oct:9, Nov:10, Dec:11 };
const cdpToISODate = v => {
  if (v === null || v === undefined || v === "") return "";
  if (v instanceof Date) return isNaN(v) ? "" : v.toISOString().slice(0, 10);
  if (typeof v === "number") { const d = new Date(Math.round((v - 25569) * 86400 * 1000)); return isNaN(d) ? "" : d.toISOString().slice(0, 10); }
  const s = String(v).trim();
  const m = s.match(/^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\s+(\d{4})$/);
  if (m) { const mi = CDP_MONTHS[m[2].slice(0,1).toUpperCase() + m[2].slice(1,3).toLowerCase()]; if (mi !== undefined) return new Date(Date.UTC(+m[3], mi, +m[1])).toISOString().slice(0, 10); }
  const d2 = new Date(s); return isNaN(d2) ? "" : d2.toISOString().slice(0, 10);
};
const CDP_POSITIONS = ["Trainee Operator", "Assistant Operator", "Slickline Operator", "Slickline Supervisor"];
const CDP_POSITION_MAP = { "Trainee Operator":"Trainee", "Helper":"Trainee", "Assistant Operator":"Assistant Operator", "Slickline Operator":"Slickline Operator", "Slickline Supervisor":"Slickline Supervisor" };
const CDP_STEP_MAP = { "Trainee":"Step 1 (T > AO)", "Assistant Operator":"Step 2 (AO > OP)", "Slickline Operator":"Step 3 (OP > SV)", "Slickline Supervisor":"Step 4 (SV > SSV)" };
const CDP_COUNTRY_MAP = { "Saudi Arabia":"KSA", "Oman":"Oman", "UAE":"UAE", "United Arab Emirates":"UAE", "Qatar":"Qatar", "Kuwait":"Kuwait", "Iraq":"Iraq", "Algeria":"Algeria", "Libya":"Libya", "Egypt":"Egypt", "India":"India", "Indonesia":"Indonesia" };

/* Parses rows already extracted from the sheet (array-of-arrays incl. header row) into
   employee-shaped objects, filtered to the four target position_desc values. Column order
   is resolved by HEADER NAME (trimmed) rather than fixed position, so a re-export with
   reordered or added columns still parses correctly; the one exception is the duplicate
   "Promotion Date" header — the first occurrence is used, the second is kept as a spare. */
function parseCDPTrackerRows(aoa) {
  if (!aoa || !aoa.length) return [];
  const header = aoa[0].map(h => (h === null || h === undefined) ? "" : String(h).trim());
  const idx = {};
  header.forEach((h, i) => { if (h && !(h in idx)) idx[h] = i; });
  const promoIdxs = header.map((h, i) => h === "Promotion Date" ? i : -1).filter(i => i >= 0);
  const get = (row, name) => (idx[name] !== undefined ? row[idx[name]] : undefined);
  const out = [];
  for (let r = 1; r < aoa.length; r++) {
    const row = aoa[r]; if (!row || !row.length) continue;
    const posSrc = get(row, "position_desc");
    if (!CDP_POSITIONS.includes(posSrc)) continue;
    const position = CDP_POSITION_MAP[posSrc];
    const rawCountry = get(row, "company_name");
    out.push({
      id: String(get(row, "employee_code") ?? "").trim(),
      name: get(row, "rpt_name") || "",
      country: CDP_COUNTRY_MAP[rawCountry] || rawCountry || "KSA",
      position,
      grade: +get(row, "grade_name") || "",
      hire: cdpToISODate(get(row, "join_date")),
      step: CDP_STEP_MAP[position] || "Step 1 (T > AO)",
      stepStart: cdpToISODate(promoIdxs.length ? row[promoIdxs[0]] : ""),
      cdp: {
        dept: get(row, "dept_name") || "",
        section: get(row, "section_name") || "",
        category: get(row, "category_name") || "",
        nationality: get(row, "nationality") || "",
        promotionDate2: cdpToISODate(promoIdxs.length > 1 ? row[promoIdxs[1]] : ""),
        match: get(row, "Match") ?? "",
        totalCredits: get(row, "TotaCredits") ?? "",
        approvedCredits: get(row, "ApprovedCredits") ?? "",
        achievedCredits: get(row, "AcheivedCredits") ?? "",
        idealDuration: get(row, "IdealDuration") ?? "",
        achievedDuration: get(row, "ACheivedDuration") ?? "",
        accountabilityByPosition: get(row, "Accountability by position") || "",
        accountabilityByDate: get(row, "Accountability by date") || "",
        finalAccountabilityStatus: get(row, "Final Accountability Status") || "",
        achievementPct: get(row, "Employee Achievement %") ?? "",
        managerApprovalPct: get(row, "Manager Approval %") ?? "",
        overdueMonths: get(row, "Overdue( In months)") ?? "",
        progressStatus: get(row, "Progress Status") || "",
        timeFrameStatus: get(row, "Time Frame Status") || "",
      },
    });
  }
  return out;
}

/* ---------------- Job Details tracker import: Name/EID/Service/Ticket#/Well/Date
   -> Experience Log rows, fanned out per Element assigned to the matched Service. ---------------- */
function parseJobDetailsRows(aoa) {
  if (!aoa || !aoa.length) return [];
  const header = aoa[0].map(h => (h === null || h === undefined) ? "" : String(h).trim());
  const idx = {};
  header.forEach((h, i) => { if (h && !(h in idx)) idx[h] = i; });
  const get = (row, name) => (idx[name] !== undefined ? row[idx[name]] : undefined);
  const out = [];
  for (let r = 1; r < aoa.length; r++) {
    const row = aoa[r]; if (!row || !row.length) continue;
    const eid = String(get(row, "EID") ?? "").trim();
    const ticket = String(get(row, "Ticket #") ?? "").trim();
    if (!eid || !ticket) continue;
    out.push({
      name: get(row, "Name") || "",
      empId: eid,
      serviceRaw: String(get(row, "Service") ?? "").trim(),
      ticket,
      well: get(row, "Well") || "",
      date: cdpToISODate(get(row, "Date")),
    });
  }
  return out;
}
const normalizeServiceName = s => {
  let t = String(s || "").trim();
  while (t.indexOf(' "') !== -1) t = t.replace(' "', '"');
  while (t.indexOf(" + ") !== -1) t = t.replace(" + ", "/");
  return t.replace(/\s+/g, " ");
};

