  th: { position:"sticky", top:0, background:C.chrome, color:"#fff", fontFamily:"'Barlow Condensed', sans-serif", fontWeight:600, fontSize:13, letterSpacing:"0.06em", textTransform:"uppercase", padding:"8px 8px", textAlign:"left", whiteSpace:"nowrap", zIndex:2 },
